library(shiny)
library(bslib)
library(DT)
library(shinyTree)

# --- INITIAL MOCK DATA (Replaces SQLite & Canvas API) ---
init_data <- function() {
  list(
    my_classes = data.frame(
      id = c(1L, 2L),
      class_type = c("canvas", "standalone"),
      canvas_id = c("99102", ""),
      canvas_name = c("STAT 2120 - Intro to Statistical Analysis", "Standalone"),
      custom_name = c("STAT 2120 (Fall)", "STAT 3110 - Math Stat"),
      description = c("Linked to Canvas demo course with pre-loaded assignments, rubrics, and grades.", 
                      "Standalone sandbox gradebook for testing custom rubric trees."),
      color = c("#E57200", "#20c997"),
      stringsAsFactors = FALSE
    ),
    students = data.frame(
      id = 1:5,
      course_id = c(1L, 1L, 1L, 1L, 2L),
      canvas_user_id = c("101", "102", "103", "104", ""),
      sortable_name = c("Cavman, Hoo", "Jefferson, Thomas", "Monroe, James", "Madison, Dolley", "Poe, Edgar Allan"),
      nickname = c("Hoo", "TJ", "", "Dolley", "Eddie"),
      notes = c("Always sits in the front row", "Great R coder", "Needs extension on HW 2", "Attends office hours regularly", "Audit student"),
      stringsAsFactors = FALSE
    ),
    assignment_groups = data.frame(
      id = 1:3,
      course_id = c(1L, 1L, 2L),
      name = c("Homework", "Exams", "Problem Sets"),
      canvas_weight = c(40, 60, 100),
      local_weight = c(40, 60, 100),
      drop_lowest = c(1, 0, 0),
      is_sync = c(1L, 1L, 0L),
      stringsAsFactors = FALSE
    ),
    assignments = data.frame(
      id = 1:4,
      course_id = c(1L, 1L, 1L, 2L),
      group_id = c(1L, 1L, 2L, 3L),
      canvas_assign_id = c("501", "502", "503", ""),
      name = c("HW 1: EDA & R Basics", "HW 2: Normal Distribution", "Midterm 1", "PS 1: Probability Bounds"),
      canvas_name = c("HW 1: EDA & R Basics", "HW 2: Normal Distribution", "Midterm 1", "PS 1: Probability Bounds"),
      canvas_group_id = c(1L, 1L, 2L, 3L),
      scoring_mode = c("negative", "negative", "negative", "positive"),
      never_drop = c(0L, 0L, 1L, 0L),
      canvas_never_drop = c(0L, 0L, 1L, 0L),
      stringsAsFactors = FALSE
    ),
    questions = data.frame(
      id = 1:6,
      assignment_id = c(1L, 1L, 1L, 2L, 3L, 4L),
      parent_id = c(NA, 1L, 1L, NA, NA, NA),
      title = c("Q1: Data Wrangling", "Q1a: Summary Stats", "Q1b: Boxplot", "Q1: Z-Scores", "Part 1: Theory", "Problem 1"),
      max_points = c(0, 10, 15, 25, 100, 50),
      stringsAsFactors = FALSE
    ),
    rubric_items = data.frame(
      id = 1:5,
      question_id = c(2L, 2L, 3L, 3L, 5L),
      description = c("Forgot na.rm = TRUE", "Incorrect SD formula", "Missing axis labels", "No title on plot", "Calculation error"),
      point_adjustment = c(-2, -3, -2, -1, -5),
      stringsAsFactors = FALSE
    ),
    subgrades = data.frame(
      student_id = c(1L, 1L, 1L, 1L,  2L, 2L, 2L, 2L,  3L, 3L, 3L, 3L,  4L, 4L, 4L, 4L),
      assignment_id = c(1L, 1L, 2L, 3L,  1L, 1L, 2L, 3L,  1L, 1L, 2L, 3L,  1L, 1L, 2L, 3L),
      question_id = c(2L, 3L, 4L, 5L,  2L, 3L, 4L, 5L,  2L, 3L, 4L, 5L,  2L, 3L, 4L, 5L),
      score = c(10, 15, 20, 95,  8, 14, 25, 88,  10, 12, 18, 92,  7, 10, 24, 84),
      stringsAsFactors = FALSE
    )
  )
}

color_choices <- c("Cavalier Orange" = "#E57200", "Rotunda Blue" = "#4B7BE5", "Sea Surface Teal" = "#20c997", "Deep Water Navy" = "#3A5A80", "Coral Pink" = "#ff7b9c", "Warm Pad Magenta" = "#e83e8c", "Rhodes Amber" = "#ffc107", "Synthwave Purple" = "#b300ff", "Slate Grey" = "#8d99ae")
custom_theme <- bs_theme(bg = "#12151A", fg = "#E0E0E0", primary = "#20c997", base_font = font_google("Inter"))

ui <- page_fillable(
  theme = custom_theme,
  tags$head(tags$style(HTML("
    body { background-image: radial-gradient(rgba(255, 255, 255, 0.05) 1.5px, transparent 1.5px); background-size: 25px 25px; }
    .modal-content, .card { background-image: none !important; }
    .breadcrumb-link:hover { color: #ffffff !important; transition: 0.2s; }
    .jstree-default .jstree-anchor { color: #E0E0E0 !important; font-family: 'Inter', sans-serif; }
    .jstree-default .jstree-clicked { background: #2a2d35 !important; border: 1px solid #20c997 !important; border-radius: 4px; }
    .split-left { border-right: 1px solid #2a2d35; height: 75vh; overflow-y: auto; padding-right: 15px; }
    .split-right { height: 75vh; overflow-y: auto; padding-left: 15px; }
    /* DT Styling */
    .dataTables_wrapper { color: #E0E0E0;}
    table.dataTable tbody tr { background-color: #1a1d24; color: #E0E0E0; }
    table.dataTable tbody tr:hover { background-color: #2a2d35 !important; }
    table.dataTable thead th { background-color: #12151A; color: #20c997; border-bottom: 2px solid #20c997 !important; font-weight: 700;}
    table.dataTable td { border-color: #2a2d35 !important; }
    table.dataTable thead tr th.dtfc-fixed-left { background-color: #12151A !important; z-index: 2; border-right: 1px solid #2a2d35; }
    table.dataTable tbody tr td.dtfc-fixed-left { background-color: #1a1d24 !important; z-index: 1; border-right: 1px solid #2a2d35; }
  "))),
  div(style = "position: absolute; top: 25px; right: 25px; z-index: 1000;", 
      span(icon("flask"), " Demo Mode (In-Memory)", style="color: #20c997; font-weight: 600; font-size: 0.9em; background: #1a1d24; padding: 8px 12px; border-radius: 20px; border: 1px solid #2a2d35;")),
  uiOutput("page_content")
)

server <- function(input, output, session) {
  mock <- init_data()
  
  rv <- reactiveValues(
    page = "home", active_class_id = NULL, active_assign_id = NULL, active_q_id = NULL,
    class_to_delete = NULL, class_to_edit = NULL, 
    my_classes = mock$my_classes,
    students = mock$students,
    assignment_groups = mock$assignment_groups,
    assignments = mock$assignments,
    questions = mock$questions,
    rubric_items = mock$rubric_items,
    subgrades = mock$subgrades,
    initialized_ids = c(),
    initialized_assign_ids = c(), assign_to_edit = NULL, assign_to_delete = NULL,
    initialized_group_ids = c(), group_to_edit = NULL, group_to_delete = NULL,
    initialized_rubric_ids = c(),
    student_to_edit = NULL, student_to_delete = NULL
  )
  
  # --- UI ROUTER ---
  output$page_content <- renderUI({
    if (rv$page == "home") { build_home_page() } 
    else if (rv$page == "course_home") { build_course_home() }
    else if (rv$page == "assignment_setup") { build_assignment_setup() }
    else if (rv$page == "grading_mode") { build_grading_mode() }
    else if (rv$page == "overall_gradebook") { build_overall_gradebook() }
    else if (rv$page == "roster_view") { build_roster_view() }
  })
  
  # --- DASHBOARD ---
  build_home_page <- function() {
    cards <- lapply(seq_len(nrow(rv$my_classes)), function(i) {
      row <- rv$my_classes[i, ]
      sub_text <- if(row$class_type == "standalone") "Standalone Gradebook" else paste("Linked to:", row$canvas_name)
      card(
        style = paste0("width: 250px; height: 300px; background-color: #1a1d24; border: 1px solid #2a2d35; border-top: 3px solid ", row$color, "; box-shadow: 0 8px 25px ", row$color, "33; flex-shrink: 0; display: flex; flex-direction: column;"),
        card_header(
          div(style = "display: flex; justify-content: space-between; align-items: center; width: 100%;", 
              span(row$custom_name, style = "overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 700; font-size: 1.15em; color: #ffffff;"),
              div(style = "display: flex; gap: 10px;", 
                  actionButton(paste0("edit_", row$id), label=NULL, icon=icon("pen"), class="btn-sm", style="background:transparent; border:none; color:#6c757d; padding:0;"), 
                  actionButton(paste0("delete_", row$id), label=NULL, icon=icon("trash"), class="btn-sm", style="background:transparent; border:none; color:#6c757d; padding:0;"))),
          style = "background-color: transparent; border-bottom: 1px solid #2a2d35; flex: 0 0 65px; display: flex; align-items: center;"
        ),
        card_body(
          class = "d-flex flex-column", style = "overflow: hidden; padding: 15px; flex: 1 1 auto;", 
          p(sub_text, style="font-size: 0.85em; color: #8d99ae; flex: 0 0 auto; margin-bottom: 12px;"),
          if (!is.na(row$description) && row$description != "") { 
            div(p(row$description, style="font-size: 0.9em; margin: 0; color: #adb5bd;"), style="overflow-y: auto; flex: 1 1 auto; min-height: 0; margin-bottom: 15px; padding-right: 5px;") 
          } else { div(style="flex: 1 1 auto;") },
          actionButton(paste0("enter_", row$id), "Enter Gradebook", style=paste0("background-color: transparent; border: 1px solid ", row$color, "; color: ", row$color, "; flex: 0 0 auto; margin-top: auto; font-weight: 600;"), class = "w-100")
        )
      )
    })
    add_card <- card(style = "width: 250px; height: 300px; background-color: transparent; border: 2px dashed #495057; box-shadow: none; flex-shrink: 0;", 
                     card_body(class = "d-flex justify-content-center align-items-center h-100", 
                               actionButton("open_create_modal", "+ Create New Class", style="background: transparent; border: none; color: #adb5bd; font-weight: 600; font-size: 1.2em;", class = "stretch-link")))
    div(class = "p-4", h2("Dashboard", style = "margin-bottom: 1.5rem; color: #ffffff; font-weight: 700;"), div(style = "display: flex; flex-wrap: wrap; gap: 1.5rem;", tagList(cards), add_card))
  }
  
  observe({
    req(nrow(rv$my_classes) > 0)
    new_ids <- setdiff(rv$my_classes$id, rv$initialized_ids)
    if (length(new_ids) > 0) {
      lapply(new_ids, function(id) {
        local({
          current_id <- id
          observeEvent(input[[paste0("enter_", current_id)]], { rv$active_class_id <- current_id; rv$page <- "course_home" }, ignoreInit = TRUE)
          observeEvent(input[[paste0("delete_", current_id)]], { rv$my_classes <- rv$my_classes[rv$my_classes$id != current_id, ] }, ignoreInit = TRUE)
          observeEvent(input[[paste0("edit_", current_id)]], { 
            rv$class_to_edit <- current_id
            curr_data <- rv$my_classes[rv$my_classes$id == current_id, ]
            showModal(modalDialog(title = "Edit Class Info", 
                                  textInput("edit_custom_name", "Display Name:", value = curr_data$custom_name), 
                                  textAreaInput("edit_description", "Course Description:", value = curr_data$description, rows = 2), 
                                  selectInput("edit_color", "Card Color:", choices = color_choices, selected = curr_data$color), 
                                  footer = tagList(modalButton("Cancel"), actionButton("save_edit_class", "Save Changes", class = "btn-success")))) 
          }, ignoreInit = TRUE)
        })
      })
      rv$initialized_ids <- c(rv$initialized_ids, new_ids)
    }
  })
  
  observeEvent(input$save_edit_class, { 
    req(input$edit_custom_name, rv$class_to_edit)
    idx <- which(rv$my_classes$id == rv$class_to_edit)
    rv$my_classes$custom_name[idx] <- input$edit_custom_name
    rv$my_classes$description[idx] <- input$edit_description
    rv$my_classes$color[idx] <- input$edit_color
    rv$class_to_edit <- NULL
    removeModal() 
  })
  
  observeEvent(input$open_create_modal, { 
    showModal(modalDialog(
      title = "Set Up a New Class", 
      radioButtons("modal_class_type", "Class Type:", choices = c("Sync with Canvas (Demo)" = "canvas", "Standalone" = "standalone"), inline = TRUE), 
      conditionalPanel(condition = "input.modal_class_type == 'canvas'", 
                       selectInput("modal_canvas_course", "Canvas Course:", choices = c("STAT 1602 - Intro Data Science" = "STAT 1602", "STAT 1100 - Chance" = "STAT 1100"))), 
      textInput("modal_custom_name", "Display Name:"), 
      textAreaInput("modal_description", "Course Description:", rows = 2), 
      selectInput("modal_color", "Card Color:", choices = color_choices), 
      footer = tagList(modalButton("Cancel"), actionButton("save_new_class", "Create Class", class = "btn-success"))
    ))
  })
  
  observeEvent(input$save_new_class, { 
    req(input$modal_custom_name)
    new_id <- if(nrow(rv$my_classes) == 0) 1L else max(rv$my_classes$id) + 1L
    c_name <- if (input$modal_class_type == "canvas") input$modal_canvas_course else "Standalone"
    c_id <- if (input$modal_class_type == "canvas") "99999" else ""
    
    new_row <- data.frame(id = new_id, class_type = input$modal_class_type, canvas_id = c_id, canvas_name = c_name, 
                          custom_name = input$modal_custom_name, description = input$modal_description, color = input$modal_color, stringsAsFactors = FALSE)
    rv$my_classes <- rbind(rv$my_classes, new_row)
    removeModal() 
  })
  
  # --- COURSE HOME ---
  build_course_home <- function() {
    active_class <- rv$my_classes[rv$my_classes$id == rv$active_class_id, ]
    is_standalone <- active_class$class_type == "standalone"
    
    groups <- rv$assignment_groups[rv$assignment_groups$course_id == rv$active_class_id, ]
    assignments <- rv$assignments[rv$assignments$course_id == rv$active_class_id, ]
    
    sync_controls <- if(!is_standalone) {
      tagList(
        actionButton("sync_canvas", "Simulate Canvas Sync", icon = icon("rotate"), style="background-color: #4B7BE5; border: none; color: white;"),
        actionButton("reset_local", "Reset to Canvas Defaults", icon = icon("undo"), style="background-color: transparent; border: 1px solid #8d99ae; color: #8d99ae;")
      )
    } else { NULL }
    
    action_bar <- div(style = "display: flex; gap: 15px; margin-bottom: 2rem; align-items: center; flex-wrap: wrap; width: 100%;",
                      sync_controls,
                      actionButton("open_create_group", "+ Create Assignment Group", icon = icon("folder-plus"), style="background-color: #2a2d35; border: 1px solid #495057; color: #E0E0E0; font-weight: 600;"),
                      actionButton("open_create_assign", "+ Create Assignment", icon = icon("file-medical"), style="background-color: #20c997; border: none; color: #12151A; font-weight: bold;"),
                      div(style = "margin-left: auto; display: flex; gap: 10px;",
                          actionButton("view_roster", "View Roster", icon = icon("users"), style="background-color: #2a2d35; border: 1px solid #495057; color: #E0E0E0; font-weight: 600;"),
                          actionButton("view_full_gradebook", "View Full Gradebook", icon = icon("table"), style="background-color: #2a2d35; border: 1px solid #495057; color: #E0E0E0; font-weight: 600;")
                      )
    )
    
    group_sections <- if(nrow(groups) > 0) {
      lapply(seq_len(nrow(groups)), function(i) {
        g <- groups[i, ]
        g_assigns <- assignments[assignments$group_id == g$id, ]
        
        cards <- lapply(seq_len(nrow(g_assigns)), function(j) {
          a <- g_assigns[j, ]
          lock_icon <- if(!is.na(a$never_drop) && a$never_drop == 1) {
            span(icon("lock"), style="color: #ffc107; font-size: 1.1em;", title="Never Drop")
          } else { NULL }
          
          card_actions <- div(style = "display: flex; align-items: center; gap: 12px; margin-left: 15px;",
                              lock_icon,
                              actionButton(paste0("edit_assign_", a$id), label = NULL, icon = icon("pen"), class = "btn-sm", style = "background: transparent; border: none; color: #6c757d; padding: 0;"),
                              actionButton(paste0("del_assign_", a$id), label = NULL, icon = icon("trash"), class = "btn-sm", style = "background: transparent; border: none; color: #dc3545; padding: 0;")
          )
          
          card(style = "background-color: #1a1d24; border: 1px solid #2a2d35; border-left: 4px solid #20c997; padding: 0; height: 65px; display: flex; justify-content: center;",
               div(style = "display: flex; justify-content: space-between; align-items: center; padding: 0 15px; width: 100%; height: 100%;",
                   div(style = "cursor: pointer; flex-grow: 1; height: 100%; display: flex; align-items: center;",
                       onclick = sprintf("Shiny.setInputValue('select_assignment', %d, {priority: 'event'});", a$id),
                       div(style="font-weight: 600; color: #ffffff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;", a$name)
                   ),
                   card_actions
               )
          )
        })
        
        div(style = "margin-bottom: 2.5rem;", 
            div(style = "display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #2a2d35; padding-bottom: 10px; margin-bottom: 15px;",
                h4(paste0(g$name, " (", g$local_weight, "%)"), style = "color: #ffffff; margin: 0; font-weight: 600;"),
                div(style = "display: flex; gap: 10px;",
                    actionButton(paste0("edit_group_", g$id), label=NULL, icon=icon("pen"), class="btn-sm", style="background: transparent; border: none; color: #6c757d; padding: 0;"),
                    actionButton(paste0("del_group_", g$id), label=NULL, icon=icon("trash"), class="btn-sm", style="background: transparent; border: none; color: #dc3545; padding: 0;")
                )
            ),
            if(length(cards) > 0) { div(style = "display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 1rem;", tagList(cards)) } else { p("No assignments in this group yet.", style="color: #6c757d; font-style: italic;") }
        )
      })
    } else {
      div(style="text-align: center; padding: 40px; background: #1a1d24; border: 1px dashed #2a2d35; border-radius: 8px;",
          p("This course is currently empty. Start by creating an assignment group.", style="color: #8d99ae; margin-bottom: 0;")
      )
    }
    
    div(class = "p-4", 
        actionLink("nav_home", "⬅ Dashboard", style="color: #adb5bd; font-weight: 600; margin-bottom: 20px; display: block;"), 
        action_bar, 
        tagList(group_sections)
    )  
  }
  
  observeEvent(input$nav_home, { rv$page <- "home" })
  observeEvent(input$select_assignment, { rv$active_assign_id <- input$select_assignment; rv$active_q_id <- NULL; rv$page <- "assignment_setup" })
  
  # --- SIMULATED SYNC & RESET ---
  observeEvent(input$sync_canvas, {
    showNotification("Demo Mode: Simulated Canvas sync complete!", type = "message")
  })
  
  observeEvent(input$reset_local, {
    req(rv$active_class_id)
    g_idx <- which(rv$assignment_groups$course_id == rv$active_class_id & rv$assignment_groups$is_sync == 1)
    if(length(g_idx) > 0) rv$assignment_groups$local_weight[g_idx] <- rv$assignment_groups$canvas_weight[g_idx]
    
    a_idx <- which(rv$assignments$course_id == rv$active_class_id & rv$assignments$canvas_assign_id != "")
    if(length(a_idx) > 0) {
      rv$assignments$never_drop[a_idx] <- rv$assignments$canvas_never_drop[a_idx]
      rv$assignments$name[a_idx] <- rv$assignments$canvas_name[a_idx]
      rv$assignments$group_id[a_idx] <- rv$assignments$canvas_group_id[a_idx]
    }
    showNotification("Local weights, rules, names, and groups reset to Canvas defaults.", type = "message")
  })
  
  # --- CREATE / EDIT / DELETE GROUP ---
  observeEvent(input$open_create_group, {
    showModal(modalDialog(
      title = "Create Assignment Group",
      textInput("new_group_name", "Group Name (e.g., Homework, Exams):"),
      numericInput("new_group_weight", "Weight Percentage (%):", value = 0, min = 0, max = 100),
      numericInput("new_group_drop", "Drop Lowest N Assignments:", value = 0, min = 0),
      footer = tagList(modalButton("Cancel"), actionButton("save_new_group", "Create Group", class = "btn-success"))
    ))
  })
  
  observeEvent(input$save_new_group, {
    req(input$new_group_name)
    new_id <- if(nrow(rv$assignment_groups) == 0) 1L else max(rv$assignment_groups$id) + 1L
    new_g <- data.frame(id = new_id, course_id = rv$active_class_id, name = input$new_group_name,
                        canvas_weight = 0, local_weight = input$new_group_weight, drop_lowest = input$new_group_drop, is_sync = 0L, stringsAsFactors = FALSE)
    rv$assignment_groups <- rbind(rv$assignment_groups, new_g)
    removeModal()
  })
  
  observe({
    req(rv$active_class_id)
    groups <- rv$assignment_groups[rv$assignment_groups$course_id == rv$active_class_id, ]
    if (nrow(groups) > 0) {
      new_group_ids <- setdiff(groups$id, rv$initialized_group_ids)
      if (length(new_group_ids) > 0) {
        lapply(new_group_ids, function(id) {
          local({
            current_id <- id
            observeEvent(input[[paste0("edit_group_", current_id)]], {
              rv$group_to_edit <- current_id
              curr_data <- rv$assignment_groups[rv$assignment_groups$id == current_id, ]
              showModal(modalDialog(
                title = "Edit Assignment Group",
                textInput("edit_group_name", "Group Name:", value = curr_data$name),
                numericInput("edit_group_weight", "Local Weight Percentage (%):", value = curr_data$local_weight, min = 0, max = 100),
                numericInput("edit_group_drop", "Drop Lowest N Assignments:", value = curr_data$drop_lowest, min = 0),
                footer = tagList(modalButton("Cancel"), actionButton("save_edit_group", "Save Changes", class = "btn-success"))
              ))
            }, ignoreInit = TRUE)
            
            observeEvent(input[[paste0("del_group_", current_id)]], {
              rv$group_to_delete <- current_id
              showModal(modalDialog(
                title = "Delete Assignment Group",
                "Are you sure you want to delete this assignment group and its assignments?",
                footer = tagList(modalButton("Cancel"), actionButton("confirm_del_group", "Yes, Delete", class = "btn-danger"))
              ))
            }, ignoreInit = TRUE)
          })
        })
        rv$initialized_group_ids <- c(rv$initialized_group_ids, new_group_ids)
      }
    }
  })
  
  observeEvent(input$save_edit_group, {
    req(input$edit_group_name, rv$group_to_edit)
    idx <- which(rv$assignment_groups$id == rv$group_to_edit)
    rv$assignment_groups$name[idx] <- input$edit_group_name
    rv$assignment_groups$local_weight[idx] <- input$edit_group_weight
    rv$assignment_groups$drop_lowest[idx] <- input$edit_group_drop
    rv$group_to_edit <- NULL
    removeModal()
  })
  
  observeEvent(input$confirm_del_group, {
    req(rv$group_to_delete)
    a_ids <- rv$assignments$id[rv$assignments$group_id == rv$group_to_delete]
    rv$subgrades <- rv$subgrades[!rv$subgrades$assignment_id %in% a_ids, ]
    q_ids <- rv$questions$id[rv$questions$assignment_id %in% a_ids]
    rv$rubric_items <- rv$rubric_items[!rv$rubric_items$question_id %in% q_ids, ]
    rv$questions <- rv$questions[!rv$questions$assignment_id %in% a_ids, ]
    rv$assignments <- rv$assignments[rv$assignments$group_id != rv$group_to_delete, ]
    rv$assignment_groups <- rv$assignment_groups[rv$assignment_groups$id != rv$group_to_delete, ]
