  output$overall_gradebook_table <- renderDT({
    students <- rv$students[rv$students$course_id == rv$active_class_id, ]
    assigns <- rv$assignments[rv$assignments$course_id == rv$active_class_id, ]
    groups <- rv$assignment_groups[rv$assignment_groups$course_id == rv$active_class_id, ]
    
    if(nrow(students) == 0) {
      return(datatable(data.frame(Notice = "No students enrolled yet."), rownames = FALSE, options = list(dom = 't', bSort = FALSE)))
    }
    
    # Calculate max points per assignment in Base R
    assigns$max_pts <- sapply(assigns$id, function(aid) {
      qs <- rv$questions[rv$questions$assignment_id == aid, ]
      if(nrow(qs) == 0) 0 else sum(qs$max_points, na.rm = TRUE)
    })
    
    df <- data.frame(
      student_id = students$id,
      Student = ifelse(!is.na(students$nickname) & students$nickname != "", 
                       paste0(students$sortable_name, ' "', students$nickname, '"'), 
                       students$sortable_name),
      Overall = "---",
      stringsAsFactors = FALSE
    )
    
    # Add Group Avg Columns
    for(g_name in groups$name) {
      df[[paste0(g_name, " Avg")]] <- "---"
    }
    # Add Assignment Columns
    for(a_name in assigns$name) {
      df[[a_name]] <- "---"
    }
    
    # Populate Grades & Compute Weighted Averages
    for(i in seq_len(nrow(df))) {
      sid <- df$student_id[i]
      stu_subs <- rv$subgrades[rv$subgrades$student_id == sid, ]
      
      total_weight <- 0
      weighted_sum <- 0
      
      for(g_idx in seq_len(nrow(groups))) {
        g <- groups[g_idx, ]
        g_assigns <- assigns[assigns$group_id == g$id & assigns$max_pts > 0, ]
        
        if(nrow(g_assigns) > 0) {
          # Get student scores for assignments in this group
          a_scores <- numeric(0)
          a_max <- numeric(0)
          a_nd <- integer(0)
          
          for(a_idx in seq_len(nrow(g_assigns))) {
            a <- g_assigns[a_idx, ]
            sub_a <- stu_subs[stu_subs$assignment_id == a$id, ]
            if(nrow(sub_a) > 0) {
              sc <- sum(sub_a$score, na.rm = TRUE)
              df[i, a$name] <- as.character(sc)
              a_scores <- c(a_scores, sc)
              a_max <- c(a_max, a$max_pts)
              a_nd <- c(a_nd, a$never_drop)
            }
          }
          
          if(length(a_scores) > 0) {
            pcts <- a_scores / a_max
            ord <- order(pcts)
            a_scores <- a_scores[ord]
            a_max <- a_max[ord]
            a_nd <- a_nd[ord]
            
            drop_n <- if(is.na(g$drop_lowest)) 0 else g$drop_lowest
            dropped <- rep(FALSE, length(a_scores))
            
            if(drop_n > 0) {
              droppable_idx <- which(a_nd == 0)
              # Keep at least 1 assignment if all are droppable
              max_to_drop <- min(drop_n, length(a_scores) - 1)
              if(length(droppable_idx) > 0 && max_to_drop > 0) {
                dropped[droppable_idx[seq_len(min(length(droppable_idx), max_to_drop))]] <- TRUE
              }
            }
            
            kept_earned <- sum(a_scores[!dropped])
            kept_poss <- sum(a_max[!dropped])
            
            if(kept_poss > 0) {
              g_pct <- kept_earned / kept_poss
              df[i, paste0(g$name, " Avg")] <- sprintf("%.2f%%", g_pct * 100)
              total_weight <- total_weight + g$local_weight
              weighted_sum <- weighted_sum + (g_pct * g$local_weight)
            }
          }
        }
      }
      if(total_weight > 0) {
        df$Overall[i] <- sprintf("%.2f%%", (weighted_sum / total_weight) * 100)
      }
    }
    
    df$student_id <- NULL
    
    datatable(df, extensions = 'FixedColumns', rownames = FALSE, options = list(
      dom = '<"d-flex justify-content-between align-items-center"lf>rt<"d-flex justify-content-between align-items-center"ip>',
